{
  "name": "Navbar",
  "parameters": [],
  "events": [],
  "domEvents": [
    {
      "name": "navbar:hide",
      "description": "Event will be triggered when Navbar becomes hidden",
      "parameters": []
    },
    {
      "name": "navbar:show",
      "description": "Event will be triggered when Navbar becomes visible",
      "parameters": []
    },
    {
      "name": "navbar:collapse",
      "description": "Event will be triggered when Navbar with large title collapsed (from large navbar to usual navbar)",
      "parameters": []
    },
    {
      "name": "navbar:expand",
      "description": "Event will be triggered when Navbar with large title expanded (from usual navbar to large navbar)",
      "parameters": []
    }
  ],
  "appMethods": [
    {
      "name": "hide",
      "description": "Hide navbar",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        },
        {
          "name": "animate",
          "type": "boolean",
          "optional": true,
          "description": ""
        },
        {
          "name": "hideStatusbar",
          "type": "boolean",
          "optional": true,
          "description": ""
        }
      ],
      "returnType": "void",
      "namespace": "navbar"
    },
    {
      "name": "show",
      "description": "Show navbar",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        },
        {
          "name": "animate",
          "type": "boolean",
          "optional": true,
          "description": ""
        }
      ],
      "returnType": "void",
      "namespace": "navbar"
    },
    {
      "name": "size",
      "description": "Recalculate positional styles for Navbar elements. It could be useful after you change some of Navbar elements dynamically. This will have effect only in iOS theme",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        }
      ],
      "returnType": "void",
      "namespace": "navbar"
    },
    {
      "name": "getElByPage",
      "description": "Get navbar HTML element by specified page element. Useful only when dynamic navbar is enabled. In this case it is out of the page container. This will have effect only in iOS theme",
      "parameters": [
        {
          "name": "pageEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        }
      ],
      "returnType": "HTMLElement",
      "namespace": "navbar"
    },
    {
      "name": "getPageByEl",
      "description": "Get page HTML element by specified Navbar element. Useful only when dynamic navbar is enabled. In this case it is out of the page container. This will have effect only in iOS theme",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        }
      ],
      "returnType": "HTMLElement",
      "namespace": "navbar"
    },
    {
      "name": "collapseLargeTitle",
      "description": "Collapse large navbar title",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        }
      ],
      "returnType": "void",
      "namespace": "navbar"
    },
    {
      "name": "expandLargeTitle",
      "description": "Expand large navbar title",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        }
      ],
      "returnType": "void",
      "namespace": "navbar"
    },
    {
      "name": "toggleLargeTitle",
      "description": "Toggle large navbar title",
      "parameters": [
        {
          "name": "navbarEl",
          "type": "HTMLElement | CSSSelector",
          "optional": false,
          "description": ""
        }
      ],
      "returnType": "void",
      "namespace": "navbar"
    }
  ],
  "appParams": [
    {
      "name": "hideOnPageScroll",
      "type": "boolean",
      "description": "Will hide Navbars on page scroll. (default false)",
      "optional": true,
      "default": "false"
    },
    {
      "name": "showOnPageScrollEnd",
      "type": "boolean",
      "description": "Set to true to show hidden Navbar when scrolling reaches end of the page. (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "showOnPageScrollTop",
      "type": "boolean",
      "description": "Set to false and hidden Navbar will not become visible when you scroll page to top everytime. They will become visible only at the most top scroll position, in the beginning of the page. (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "scrollTopOnTitleClick",
      "type": "boolean",
      "description": "When enabled then every click on navbar's title element will scroll related page to the top. (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "iosCenterTitle",
      "type": "boolean",
      "description": "When enabled then it will position title at the center in iOS theme. This will have effect only in iOS theme. (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "mdCenterTitle",
      "type": "boolean",
      "description": "When enabled then it will position title at the center in MD theme. This will have effect only in MD theme. (default false)",
      "optional": true,
      "default": "false"
    },
    {
      "name": "collapseLargeTitleOnScroll",
      "type": "boolean",
      "description": "When enabled it will collapse large title on page scroll (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "snapPageScrollToLargeTitle",
      "type": "boolean",
      "description": "When enabled it will snap page scroll to large title (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "snapPageScrollToTransparentNavbar",
      "type": "boolean",
      "description": "When enabled it will snap page scroll to transparent title (default true)",
      "optional": true,
      "default": "true"
    }
  ],
  "appEvents": [
    {
      "name": "navbarHide",
      "description": "Event will be triggered when Navbar becomes hidden",
      "parameters": [
        {
          "name": "el",
          "type": "HTMLElement",
          "description": ""
        }
      ]
    },
    {
      "name": "navbarShow",
      "description": "Event will be triggered when Navbar becomes visible",
      "parameters": [
        {
          "name": "el",
          "type": "HTMLElement",
          "description": ""
        }
      ]
    },
    {
