{
  "name": "Sheet",
  "parameters": [
    {
      "name": "el",
      "type": "HTMLElement | CSSSelector",
      "description": "Sheet Modal element. Can be useful if you already have Sheet Modal element in your HTML and want to create new instance using this element.",
      "optional": true
    },
    {
      "name": "content",
      "type": "string",
      "description": "Full Sheet Modal HTML layout string. Can be useful if you want to create Sheet Modal element dynamically.",
      "optional": true
    },
    {
      "name": "backdrop",
      "type": "boolean",
      "description": "Enables Sheet Modal backdrop (dark semi transparent layer behind). (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "backdropEl",
      "type": "HTMLElement | CSSSelector",
      "description": "Backdrop element to share across instances",
      "optional": true
    },
    {
      "name": "backdropUnique",
      "type": "boolean",
      "description": "If enabled it creates unique backdrop element exclusively for this modal (default false)",
      "optional": true,
      "default": "false"
    },
    {
      "name": "scrollToEl",
      "type": "HTMLElement | CSSSelector",
      "description": "HTML element or string (with CSS selector) of element. If specified, then sheet will try to scroll page content to this element on open",
      "optional": true
    },
    {
      "name": "closeByBackdropClick",
      "type": "boolean",
      "description": "When enabled, Sheet Modal will be closed on backdrop click. (default true)",
      "optional": true,
