{
  "name": "View",
  "parameters": [
    {
      "name": "initRouterOnTabShow",
      "type": "boolean",
      "description": "If enabled and View is tab, it won't initialize router and load initial page until View tab becomes visible",
      "optional": true
    },
    {
      "name": "name",
      "type": "string",
      "description": "View name. If view was created with name, then it may be accessed via app.views.[name]",
      "optional": true
    },
    {
      "name": "main",
      "type": "boolean",
      "description": "Specify whether this is View is main or not. If not passed then will be determined based on whether its element has view-main class or not",
      "optional": true
    },
    {
      "name": "router",
      "type": "boolean",
      "description": "Set to false to disable view router",
      "optional": true
    },
    {
      "name": "url",
      "type": "string",
      "description": "Default (initial) View's url. If not specified, then it is equal to document url",
      "optional": true
    },
    {
      "name": "linksView",
      "type": "CSSSelector | View",
      "description": "CSS Selector of another view or object with initialized View instance. By default all links in initialized (only) view will load pages in this view. This tell links to load pages in other view.",
      "optional": true
    },
    {
      "name": "allowDuplicateUrls",
      "type": "boolean",
      "description": "You may enable this parameter to allow loading of new pages that have same url as currently \"active\" page in View.",
      "optional": true
    },
    {
      "name": "animate",
      "type": "boolean",
      "description": "Enables transitions between pages",
      "optional": true
    },
    {
      "name": "transition",
      "type": "string",
      "description": "Custom page transition effect name",
      "optional": true
    },
    {
      "name": "preloadPreviousPage",
      "type": "boolean",
      "description": "Enable/disable preloading of previous page when you go deep in navigation. Should be enabled for correct work of \"swipe back page\" feature.",
      "optional": true
    },
    {
      "name": "reloadPages",
      "type": "boolean",
      "description": "When enabled, View will always reload currently active page without loading new one",
      "optional": true
    },
    {
      "name": "reloadDetail",
      "type": "boolean",
      "description": "When enabled it will reload every detail page when navigating (by default false)",
      "optional": true
    },
    {
      "name": "masterDetailBreakpoint",
      "type": "number",
      "description": "Minimum app width to enable Master Detail view for master routes (routes with master: true parameter)",
      "optional": true
    },
    {
      "name": "masterDetailResizable",
      "type": "boolean",
      "description": "Enables resizable Master Detail",
      "optional": true
    },
    {
      "name": "restoreScrollTopOnBack",
      "type": "boolean",
      "description": "When enabled it will restore page scroll top when you get back to this page",
      "optional": true
    },
    {
      "name": "iosPageLoadDelay",
      "type": "number",
      "description": "Delay (in ms) after new page will be loaded and inserted to DOM and before it will be transitioned. Can be increased a bit to improve performance. Will have effect only under iOS theme",
      "optional": true
    },
    {
      "name": "mdPageLoadDelay",
      "type": "number",
      "description": "Delay (in ms) after new page will be loaded and inserted to DOM and before it will be transitioned. Can be increased a bit to improve performance. Will have effect only under MD theme",
      "optional": true
    },
    {
      "name": "passRouteQueryToRequest",
      "type": "boolean",
      "description": "When enabled then router will pass route url query to request url query (for url, componentUrl route properties)",
      "optional": true
    },
    {
      "name": "passRouteParamsToRequest",
      "type": "boolean",
      "description": "When enabled then router will pass current route parameters to request url query (for url, componentUrl route properties)",
      "optional": true
    },
    {
      "name": "routes",
      "type": "Router.RouteParameters[]",
      "description": "Array with current View routes. In case if specified then will overwrite global app routes and routes only specified here will be available for the current View",
      "optional": true
    },
    {
      "name": "routesAdd",
      "type": "Router.RouteParameters[]",
      "description": "Array with additional routes that will extend global app routes. This additional routes will only be available for the current View",
      "optional": true
    },
    {
      "name": "removeElements",
      "type": "boolean",
      "description": "During page transitions Router may remove unused Page and Navbar elements from DOM. Useful to be disabled in case you want to handle elements removal manually or using other library, e.g. Vue or React",
      "optional": true
    },
    {
      "name": "removeElementsWithTimeout",
      "type": "boolean",
      "description": "When enabled then Router will remove elements after timeout",
      "optional": true
    },
    {
      "name": "removeElementsTimeout",
      "type": "number",
      "description": "Timeout to remove elements (in case of removeElementsWithTimeout: true)",
      "optional": true
    },
    {
