      "optional": true
    },
    {
      "name": "xhrCacheIgnore",
      "type": "string[]",
      "description": "Array of URLs (string) that should not be cached",
      "optional": true
    },
    {
      "name": "xhrCacheIgnoreGetParameters",
      "type": "boolean",
      "description": "If \"true\" then URLs like \"about.html?id=2\" and \"about.html?id=3\" will be treated and cached like single \"about.html\" page",
      "optional": true
    },
    {
      "name": "xhrCacheDuration",
      "type": "number",
      "description": "Duration in ms (milliseconds) while app will use cache instead of loading page with another Ajax request. By default it takes 10 minutes.",
      "optional": true
    },
    {
      "name": "componentCache",
