      "optional": true,
      "default": "true"
    },
    {
      "name": "iosSwipeBack",
      "type": "boolean",
      "description": "Enable/disable ability to swipe back from left edge of screen to get to the previous page. For iOS theme",
      "optional": true
    },
    {
      "name": "iosSwipeBackThreshold",
      "type": "number",
