      "optional": true
    },
    {
      "name": "iosSwipeBackAnimateShadow",
      "type": "boolean",
      "description": "Enable/disable box-shadow animation during swipe back action. You can disable it to improve performance. For iOS theme",
      "optional": true
    },
    {
      "name": "iosSwipeBackAnimateOpacity",
      "type": "boolean",
      "description": "Enable/disable opacity animation during swipe back action. You can disable it to improve performance. For iOS theme",
      "optional": true
    },
    {
      "name": "mdSwipeBack",
      "type": "boolean",
      "description": "Enable/disable ability to swipe back from left edge of screen to get to the previous page. For MD theme",
      "optional": true
    },
    {
      "name": "mdSwipeBackThreshold",
      "type": "number",
