      "optional": true
    },
    {
      "name": "mdSwipeBackAnimateShadow",
      "type": "boolean",
      "description": "Enable/disable box-shadow animation during swipe back action. You can disable it to improve performance. For MD theme",
      "optional": true
    },
    {
      "name": "mdSwipeBackAnimateOpacity",
      "type": "boolean",
      "description": "Enable/disable opacity animation during swipe back action. You can disable it to improve performance. For MD theme",
      "optional": true
    },
    {
      "name": "browserHistory",
      "type": "boolean",
      "description": "If you develop web app (not Cordova/Capacitor or Home Screen web app) it is useful to enable hash navigation (browser url will look like \"http://my-webapp.com/#!/about.html\"). User as well will be able to navigate through app's history by using browser's default back and forward buttons.",
      "optional": true
    },
    {
      "name": "browserHistoryRoot",
      "type": "string",
      "description": "Browser history root URL, for example \"http://my-app.com/\". It is useful only in case when you use empty (\"\") browserHistorySeparator",
      "optional": true
    },
    {
      "name": "browserHistoryAnimate",
      "type": "boolean",
      "description": "Enable/disable page transitions on history change",
      "optional": true
    },
    {
      "name": "browserHistoryAnimateOnLoad",
      "type": "boolean",
      "description": "Enable/disable page transition on app load",
      "optional": true
    },
    {
      "name": "browserHistorySeparator",
      "type": "string",
      "description": "Browser history URL separator, can be changed for something like '#page/' and then your URLs will look like \"http://myapp.com/#page/about.html\"",
      "optional": true
    },
    {
      "name": "browserHistoryOnLoad",
      "type": "boolean",
      "description": "Disable to ignore parsing browser history URL and loading page on app load",
      "optional": true
    },
    {
      "name": "browserHistoryInitialMatch",
      "type": "boolean",
      "description": "Set to true when your server cofigured to respond with content that matches to requested URL (e.g. using with server-side rendering frameworks like Nuxt.js, Next.js, and others). Also must be enabled when used in Framework7-React/Vue/Svelte. By default disabled",
      "optional": true
    },
    {
      "name": "browserHistoryStoreHistory",
      "type": "boolean",
      "description": "When enabled (by default), it will store router history in localStorage and try to restore it on next web app visit",
      "optional": true
    },
    {
      "name": "browserHistoryTabs",
      "type": "'replace' | 'push'",
      "description": "When \"replace\" (by default), it will replace state on routable tabs change, otherwise (if \"push\"), it will add to history every routable tab change, so it will be possible to switch back between tabs with browser back button",
