{
  "name": "Searchbar",
  "parameters": [
    {
      "name": "el",
      "type": "HTMLElement | CSSSelector",
      "description": "Searchbar element. HTMLElement or string with CSS selector of searchbar element",
      "optional": false
    },
    {
      "name": "inputEl",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTML element of searchbar input element. By default (if not passed) will try to look for input type=\"search\" inside of searchbar",
      "optional": true
    },
    {
      "name": "disableButton",
      "type": "boolean",
      "description": "Enables disable button (default true)",
      "optional": true,
      "default": "true"
    },
    {
      "name": "disableButtonEl",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTML element of searchbar disable button. By default (if not passed) will try to look for element with search-disable-button class inside of searchbar",
      "optional": true
    },
    {
      "name": "searchContainer",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTML element of list block to search in",
      "optional": true
    },
    {
      "name": "searchIn",
      "type": "CSSSelector",
      "description": "CSS selector of List View element's field where we need to search. Usually we search through element titles, in this case we need to pass .item-title. It is also possible to pass few elements for search like .item-title, .item-text",
      "optional": true
    },
    {
      "name": "searchItem",
      "type": "CSSSelector",
      "description": "CSS selector of single search item. If we do a search in List View, then it must be a single list element li (default \"li\")",
      "optional": true,
      "default": "\"li\""
    },
    {
      "name": "searchGroup",
      "type": "CSSSelector",
      "description": "CSS selector of group element. Used when hideGroups enabled to hide groups. If we do a search in List View, then it usually a list group (default \"list-group\")",
      "optional": true,
      "default": "\"list-group\""
    },
    {
      "name": "searchGroupTitle",
      "type": "CSSSelector",
      "description": "CSS selector of group titles. Used when hideGroupTitles enabled to hide group titles. If we do a search in List View, then it usually a list group title (default \".list-group-title\")",
      "optional": true,
      "default": "\".list-group-title\""
    },
    {
      "name": "foundEl",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTMLElement of searchbar \"found\" element to make it hidden when there is no search results (default \".searchbar-found\")",
      "optional": true,
      "default": "\".searchbar-found\""
    },
    {
      "name": "notFoundEl",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTMLElement of searchbar \"not-found\" element to make it visible when there is no search results (default \".searchbar-not-found\")",
      "optional": true,
      "default": "\".searchbar-not-found\""
    },
    {
      "name": "hideOnEnableEl",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTMLElement of elements to be hidden when searchbar enabled (default \".searchbar-hide-on-enable\")",
      "optional": true,
      "default": "\".searchbar-hide-on-enable\""
    },
    {
      "name": "hideOnSearchEl",
      "type": "HTMLElement | CSSSelector",
      "description": "CSS selector or HTMLElement of elements to be hidden on searchbar search (default \".searchbar-hide-on-search\")",
      "optional": true,
      "default": "\".searchbar-hide-on-search\""
    },
    {
      "name": "backdrop",
      "type": "boolean",
      "description": "Enables searchbar backdrop element. (default true)",
      "optional": true,
      "default": "true"
    },
    {
