      "type": "boolean",
      "description": "If enabled it creates unique backdrop element exclusively for this modal (default false)",
      "optional": true,
      "default": "false"
    },
    {
      "name": "cssClass",
      "type": "string",
      "description": "Custom css class added to Actions Sheet element",
      "optional": true
    },
    {
      "name": "closeByBackdropClick",
      "type": "boolean",
      "description": "When enabled, action sheet will be closed on backdrop click",
      "optional": true
    },
    {
